"  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [settingsActiveTab, setSettingsActiveTab] = useState('general');

  useEffect(() => {
    if (isSettingsModalOpen) {
      const allowedSubTabs = [
         { id: 'general', key: 'general' },
         { id: 'outlet', key: 'general' },
         { id: 'printer', key: 'printers' },
         { id: 'shortcuts', key: 'shortcuts' },
         { id: 'formatting', key: 'formatting' },
         { id: 'profile', key: 'profile' }
      ].filter(tab => {
         const posAccess = business?.staff_permissions?.pos_access;
         if (!posAccess) return true;
         const userRole = String(business?.role || '').toLowerCase();
         const isSupervisor = ['brand_owner', 'master_admin', 'admin', 'manager'].includes(userRole) || userRole.includes('admin') || userRole.includes('manager');
         if (isSupervisor) return true;
         return posAccess?.Settings?.[tab.key] !== false;
      });
      if (allowedSubTabs.length > 0) {
        if (!allowedSubTabs.find(t => t.id === settingsActiveTab)) {
          setSettingsActiveTab(allowedSubTabs[0].id);
        }
      }
    }
  }, [isSettingsModalOpen, business, settingsActiveTab]);"
